import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';
const db=openDatabase();
let stopping=false; let active=false;
for(const signal of ['SIGINT','SIGTERM'] as const)process.on(signal,()=>{stopping=true;});
const beat=()=>db.prepare('INSERT INTO worker_heartbeat(singleton,seen_at) VALUES(1,?) ON CONFLICT(singleton) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
beat(); const heartbeat=setInterval(()=>{try{beat()}catch{}},500); heartbeat.unref();
function recoverRunning(){
 const rows=db.prepare(\"SELECT * FROM jobs WHERE status='running' ORDER BY seq\").all() as JobRow[];
 for(const job of rows)db.prepare(\"UPDATE jobs SET completed=0,output=NULL,error=NULL,updated_at=? WHERE id=? AND status='running'\").run(new Date().toISOString(),job.id);
 return rows;
}
async function processJob(job:JobRow,recovered=false){
 active=true;
 let attempt=job.attempts;
 if("'!recovered){db.prepare("UPDATE jobs SET status='"'running',attempts=attempts+1,completed=0,output=NULL,error=NULL,updated_at=? WHERE id=? AND status='queued'\").run(new Date().toISOString(),job.id);attempt+=1;}
 else db.prepare(\"UPDATE jobs SET completed=0,output=NULL,error=NULL,updated_at=? WHERE id=? AND status='running'\").run(new Date().toISOString(),job.id);
 const current=db.prepare('SELECT * FROM jobs WHERE id=?').get(job.id) as JobRow;
 for(let step=1;step<=current.steps;step++){
  await sleep(100); if(stopping){active=false;return;}
  if(step===1 && attempt<=current.fail_attempts){
   const now=new Date().toISOString();
   if(attempt>=3)db.prepare(\"UPDATE jobs SET status='failed',completed=0,output=NULL,error='transient failure',updated_at=? WHERE id=?\").run(now,current.id);
   else db.prepare(\"UPDATE jobs SET status='queued',completed=0,output=NULL,error=NULL,available_at=?,updated_at=? WHERE id=?\").run(Date.now()+500,now,current.id);
   active=false;return;
  }
  const now=new Date().toISOString();
  if(step===current.steps)db.prepare(\"UPDATE jobs SET completed=?,status='completed',output=?,error=NULL,updated_at=? WHERE id=? AND status='running'\").run(step,current.input.toUpperCase(),now,current.id);
  else db.prepare(\"UPDATE jobs SET completed=?,updated_at=? WHERE id=? AND status='running'\").run(step,now,current.id);
 }
 active=false;
}
try{
 const recovered=recoverRunning();
 for(const job of recovered){if(stopping)break; await processJob(job,true);}
 while("'!stopping){
  beat();
  const row=db.prepare("SELECT * FROM jobs WHERE status='"'queued' AND available_at<=? ORDER BY seq LIMIT 1\").get(Date.now()) as JobRow|undefined;
  if("'!row){await sleep(100);continue;}
  await processJob(row);
 }
} finally {
 clearInterval(heartbeat);
 try{db.prepare('"'DELETE FROM worker_heartbeat WHERE singleton=1').run();}catch{}
 db.close();
}
